import io
import dotenv

def test_values_precedence(monkeypatch):
    monkeypatch.setenv('A', 'environment')
    text = 'A=file\nB=${A}\n'
    assert dotenv.dotenv_values(stream=io.StringIO(text), override=False) == {'A':'file', 'B':'environment'}
    assert dotenv.dotenv_values(stream=io.StringIO(text)) == {'A':'file', 'B':'file'}

